# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import OutsideHoursError, uncovered_gaps

HOURS = "08:00-18:00"

def gaps_for(worked, hours=HOURS):
    spans = [parse_span(text) for text in worked]
    return uncovered_gaps(spans, parse_span(hours))

class UncoveredGapTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        result = gaps_for(["08:00-12:00", "13:00-18:00"])
        expect = ["gap 12:00-13:00 (60 min)"]
        self.assertEqual(result, expect)

    def test_gaps_at_both_ends(self):
        result = gaps_for(["09:00-17:00"])
        self.assertEqual(result, [
            "gap 08:00-09:00 (60 min)",
            "gap 17:00-18:00 (60 min)"
        ])

    def test_full_coverage_has_no_gaps(self):
        self.assertEqual(gaps_for(["08:00-18:00"]), [])

    def test_touching_and_overlapping_spans(self):
        worked = ["08:00-10:00", "10:00-12:00"]
        worked.append("11:00-18:00")
        self.assertEqual(gaps_for(worked), [])

    def test_no_spans_is_one_big_gap(self):
        result = gaps_for([])
        expect = ["gap 08:00-18:00 (600 min)"]
        self.assertEqual(result, expect)

    def test_unsorted_input(self):
        result = gaps_for(["14:00-18:00", "08:00-12:00"])
        expect = ["gap 12:00-14:00 (120 min)"]
        self.assertEqual(result, expect)

    def test_generator_input(self):
        spans = (Span(480, 600) for item in range(1))
        result = uncovered_gaps(spans, Span(480, 720))
        expect = ["gap 10:00-12:00 (120 min)"]
        self.assertEqual(result, expect)

class OutsideHoursTests(unittest.TestCase):
    def test_starting_early_raises(self):
        with self.assertRaises(OutsideHoursError):
            gaps_for(["07:00-12:00"])

    def test_ending_late_raises(self):
        with self.assertRaises(OutsideHoursError):
            gaps_for(["12:00-18:30"])

    def test_error_is_a_value_error(self):
        with self.assertRaises(ValueError):
            gaps_for(["00:00-24:00"])

if __name__ == "__main__":
    unittest.main()
